L000025	\title{Universality of stochastic control of quantum chaos with measurement and feedback}
L000026	
L000027	\author{Andrew A. Allocca}
L000028	\affiliation{Department of Physics and Astronomy, Louisiana State University, Baton Rouge, Louisiana 70803, USA}
L000029	\affiliation{Center for Computation and Technology, Louisiana State University, Baton Rouge, Louisiana 70803, USA}
