L000676	\section{Eigenvectors of the Stochastic Evolution}
L000677	
L000678	The stochastic dynamics we consider generates time evolution in the Heisenberg picture as
L000679	\begin{equation}
L000680	    \mathbb{T}[\hat{\mathcal{O}}(t+1)] = (1-p) \mathbb{S}_\kappa[\hat{\mathcal{O}}(t)] + p\, \mathbb{C}_\gamma[\hat{\mathcal{O}}(t)],
L000681	\end{equation}
L000682	where $\hat{\mathcal{O}}$ is a generic operator, and $\mathbb{S}_\kappa$ and $\mathbb{C}_\gamma$ are the squeezing and control channels.
L000683	While all the eigenvectors of the individual channels $\mathbb{S}_\kappa$ and $\mathbb{C}_\gamma$ are simple to calculate, eigenvectors for the full channel $\mathbb{T}$ are not as straightforward to obtain.
L000684	Here, we now construct an infinite set of these eigenvectors that will allow us to draw important conclusions about the controlled phase of this model.
L000685	
L000686	We first note the useful identities
L000687	\begin{gather}
L000688	    (\hat{v}_+)^k = \sum_{l=0}^{\floor{k/2}} \underbrace{\frac{(2l-1)!!}{2^l} \binom{k}{2l}}_{\equiv \mathcal{A}_{k,k-2l}} \,:(\hat{v}_+)^{k-2l}: \,\, =\,\, :(\hat{v}_+)^k: + \sum_{l=1}^{\floor{k/2}}\mathcal{A}_{k,k-2l}\,:(\hat{v}_+)^{k-2l}:\label{eq:id1}\\
L000689	    :(\hat{v}_+)^k:\,\, = \sum_{l=0}^{\floor{k/2}} \underbrace{(-1)^l \frac{(2l-1)!!}{2^l} \binom{k}{2l}}_{\equiv (\mathcal{A}^{-1})_{k,k-2l}} (\hat{v}_+)^{k-2l},\label{eq:id2}
L000690	\end{gather}
L000691	allowing us to transform between $(\hat{v}_+)^k$ and $:(\hat{v}_+)^k:$, where
L000692	\begin{equation}
L000693	    :(\hat{v}_+)^k:\, = \left(\frac{e^{-i\frac{\pi}{4}}}{\sqrt{2}}\right)^k\sum_{j=0}^k\binom{k}{j}(i\hat{a}^\dagger)^j\hat{a}^{k-j}
L000694	\end{equation}
L000695	has normally-ordered ladder operators, so that
L000696	\begin{equation}
L000697	    \mathbb{C}_\gamma[:(\hat{v}_+)^k:] = e^{-k\gamma} :(\hat{v}_+)^k:.
L000698	\end{equation}
L000699	\cref{eq:id1} is simple to derive, and we obtain \cref{eq:id2} by noting that $\mathcal{A}_{k,k'}$ are the components of a triangular matrix---we have only nonzero elements for $k>k'$.
L000700	The properties of triangular matrices then allow direct computation of $\mathcal{A}^{-1}$.
L000701	
L000702	Two low-order eigenvectors of $\mathbb{T}$ are straightforward:
L000703	\begin{align}
L000704	    \mathbb{S}_\kappa[\hat{1}] = \mathbb{C}_\gamma[\hat{1}] = \hat{1}  \quad&\Rightarrow\quad \mathbb{T}[\hat{1}] = \hat{1}\\
L000705	    \mathbb{S}_\kappa[\hat{v}_+] = e^{\kappa}\hat{v}_+, \quad\mathbb{C}_\gamma[\hat{v}_+] = e^{-\gamma}\,\hat{v}_+ \quad&\Rightarrow\quad \mathbb{T}[\hat{v}_+] = \left[(1-p)e^{\kappa} + p\,e^{-\gamma}\right]\hat{v}_+.
L000706	\end{align}
L000707	so we can define the corresponding eigenvalues $\lambda_0 = 1$ and $\lambda_1(p) = (1-p)e^{\kappa}+p\,e^{-\gamma}$.
L000708	We now build eigenvectors of $\mathbb{T}$ inductively using these as base cases.
L000709	
L000710	Assume that for some fixed $n$ we have a set of operators $\{\hat{Z}_k\}$ for $k=0,2,\dots,n-2$ ($n$ even) or $k=1,3,\dots,n-2$ ($n$ odd), with $\hat{Z}_0\equiv\hat{1}$, $\hat{Z}_1\equiv \hat{v}_+$, and
L000711	\begin{equation}
L000712	    \mathbb{T}[\hat{Z}_k] = \lambda_k(p) \hat{Z}_k,
L000713	\end{equation}
L000714	with known eigenvalues $\lambda_k(p)$.
L000715	Additionally, assume that we know how to write any of these $\hat{Z}_k$ as a sum over the operators in this set with smaller index as
L000716	\begin{equation}
L000717	    \hat{Z}_k = (\hat{v}_+)^k + \sum_{l=1}^{\floor{k/2}} \alpha_{k,k-2l} \hat{Z}_{k-2l} = \sum_{l=0}^{\floor{k/2}} \beta_{k,k-2l} (\hat{v}_+)^{k-2l}, \label{eq:Zeq}
L000718	\end{equation}
L000719	where all coefficients $\alpha_{k,k-2l}$ are known and the coefficients $\beta_{k,k-2l}$ can be written in terms of the $\alpha$s by expanding all $\hat{Z}_{k-2l}$ in this same way and collecting powers of $\hat{v}_+$---the first few are $\beta_{k,k}=1$, $\beta_{k,k-2}=\alpha_{k,k-2}$, and $\beta_{k,k-4}=\alpha_{k,k-4}+\alpha_{k,k-2}\alpha_{k-2,k-4}$.
L000720	For $n=2$ or $3$ the set of known operators is simply $\hat{Z}_0 = \hat{1}$ or $\hat{Z}_1 = \hat{v}_+$ alone, and these expansions are trivial.
L000721	
L000722	Now write a new operator,
L000723	\begin{equation} \label{eq:alphaansatz}
L000724	    \hat{Z}_n = (\hat{v}_+)^n + \sum_{k=1}^{\floor{n/2}}\alpha_{n,n-2k}\hat{Z}_{n-2k}  = (\hat{v}_+)^n + \sum_{k=1}^{\floor{n/2}}\beta_{n,n-2k} (\hat{v}_+)^{n-2k}
L000725	\end{equation}
L000726	where $\alpha_{n,n-2k}$ are $\floor{n/2}$ undetermined constants, one for each $k$, and $\beta_{n,n-2k}$ can be written in terms of these $\alpha$s as in \cref{eq:Zeq}.
L000727	This new operator evolves under $\mathbb{T}$ as
L000728	\begin{align*}
L000729	    \mathbb{T}[\hat{Z}_n] &= \mathbb{T}[(\hat{v}_+)^n] + \sum_{k=1}^{\floor{n/2}}\alpha_{n,n-2k}\mathbb{T}[\hat{Z}_{n-2k}] \\
L000730	    & = (1-p)\mathbb{S}_{\kappa}[(\hat{v}_+)^n] + p\,\sum_{k=0}^{\floor{n/2}}\mathcal{A}_{n,n-2k}\mathbb{C}_{\gamma}\left[:(\hat{v}_+)^{n-2k}:\right] + \sum_{k=1}^{\floor{n/2}}\alpha_{n,n-2k}\lambda_{n-2k}(p)\hat{Z}_{n-2k} \\
L000731	    & = (1-p)e^{n\kappa}(\hat{v}_+)^n + p\,\underbrace{\sum_{k=0}^{\floor{n/2}}\mathcal{A}_{n,n-2k}e^{-(n-2k)\gamma}:(\hat{v}_+)^{n-2k}:}_{\text{separate out } k=0 \text{ term, noting } \mathcal{A}_{n,n}=1} + \sum_{k=1}^{\floor{n/2}}\alpha_{n,n-2k}\lambda_{n-2k}(p)\hat{Z}_{n-2k} \\
L000732	    & = (1-p) e^{n\kappa} (\hat{v}_+)^n + p\,e^{-n\gamma} \underbrace{:(\hat{v}_+)^n:}_{\text{use \cref{eq:id1}}} +\, p\sum_{k=1}^{\floor{n/2}}\mathcal{A}_{n,n-2k} e^{-(n-2k)\gamma}:(\hat{v}_+)^{n-2k}: + \sum_{k=1}^{\floor{n/2}}\alpha_{n,n-2k}\lambda_{n-2k}(p)\hat{Z}_{n-2k} \\
L000733	    & = \underbrace{\left[(1-p) e^{n\kappa} + p\,e^{-n\gamma}\right]}_{\equiv \lambda_n(p)}(\hat{v}_+)^n + p\sum_{k=1}^{\floor{n/2}}\mathcal{A}_{n,n-2k}\left[e^{-(n-2k)\gamma}-e^{-n\gamma}\right] :(\hat{v}_+)^{n-2k}: + \sum_{k=1}^{\floor{n/2}}\alpha_{n,n-2k}\lambda_{n-2k}(p)\hat{Z}_{n-2k} \\
L000734	    & = \lambda_n(p)\hat{Z}_n + \sum_{k=1}^{\floor{n/2}}\left\{p\,\mathcal{A}_{n,n-2k} \left[e^{-(n-2k)\gamma}-e^{-n\gamma}\right] :(\hat{v}_+)^{n-2k}: + \alpha_{n,n-2k}\left[\lambda_{n-2k}(p)-\lambda_n(p)\right]\hat{Z}_{n-2k}\right\}\\
L000735	\end{align*}
L000736	We now use \cref{eq:id2} and \cref{eq:Zeq} to express all operators in the expression in brackets as powers of $\hat{v}_+$, and re-indexing and reordering the sums gives
L000737	\begin{align}
L000738	    \mathbb{T}[\hat{Z}_n] &= \lambda_n(p)\hat{Z}_n + \sum_{l=1}^{\floor{n/2}} \sum_{k=1}^{l} \Bigg\{ p\,\left[e^{-(n-2k)\gamma}-e^{-n\gamma}\right]\,\mathcal{A}_{n,n-2k}(\mathcal{A}^{-1})_{n-2k,n-2l} \nonumber \\
L000739	    & \hspace{6cm} + \left[\lambda_{n-2k}(p)-\lambda_n(p)\right]\,\alpha_{n,n-2k}\beta_{n-2k,n-2l} \Bigg\} (\hat{v}_+)^{n-2l} \\
L000740	    &\equiv \lambda_n(p)\hat{Z}_n + \sum_{k=1}^{\floor{n/2}} \mathcal{C}_{n,n-2k}\,(\hat{v}_+)^{n-2k}.
L000741	\end{align}
L000742	Demanding that all of the $\floor{n/2}$ coefficients $\mathcal{C}_{n,n-2k}$ vanish enforces particular values for the unknowns $\alpha_{n,n-2k}$.
L000743	This demand can always be satisfied because $\mathcal{C}$ can be expressed as a triangular matrix multiplying a vector of powers of $\hat{v}_+$.
L000744	For $k=1$, $\mathcal{C}_{n,n-2}=0$ gives an equation that contains only a single unknown, $\alpha_{n,n-2}$, and we find
L000745	\begin{equation}
L000746	    \alpha_{n,n-2} = \frac{p\,\left[e^{-(n-2)\gamma}-e^{-n\gamma}\right]\,\mathcal{A}_{n,n-2}(\mathcal{A}^{-1})_{n-2,n-2}}{\left[\lambda_{n-2}(p)-\lambda_n(p)\right]\,\beta_{n-2,n-2}},
L000747	\end{equation}
L000748	entirely in terms of known quantities.
L000749	For $k=2$, $\mathcal{C}_{n,n-4} = 0$ gives an equation that depends on $\alpha_{n,n-4}$ and the now determined $\alpha_{n,n-2}$, allowing for the former to be obtained explicitly.
L000750	The pattern continues, allowing us to solve for all $\alpha_{n,n-2k}$ in sequence.
L000751	
L000752	In the end we are left with
L000753	\begin{equation}
L000754	    \mathbb{T}[\hat{Z}_n] = \lambda_n(p) \hat{Z}_n
L000755	\end{equation}
L000756	so this posited operator is a new eigenvector of $\mathbb{T}$ with eigenvalue $\lambda_n(p) = (1-p)e^{n\kappa}+p\,e^{-n\gamma}$.
L000757	We can repeat this process \textit{ad infinitum} to construct an infinite tower of eigenvectors and eigenvalues for all integers $n$.
L000758	This also confirms the consistency of the assumed form of the operators $\hat{Z}_k$ in \cref{eq:Zeq}.
L000759	We can also rewrite \cref{eq:alphaansatz} as
L000760	\begin{equation} \label{eq:alphaZ}
L000761	    (\hat{v}_+)^n = \hat{Z}_n - \sum_{k=1}^{\floor{n/2}}\alpha_{n,n-2k}\hat{Z}_{n-2k},
L000762	\end{equation}
L000763	giving a way to express any power of $\hat{v}_+$ in terms of eigenvectors $\{\hat{Z}_k\}$.
L000764	
L000765	\subsection{Operator evolution and critical points}
L000766	Though the set $\{\hat{Z}_n\}$ does not comprise a complete set of eigenvectors of $\mathbb{T}$, it allows us to examine the controllability of generic operators.
L000767	With repeated application of $\mathbb{T}$, the operators $\hat{Z}_n$ acquire factors of the corresponding $\lambda_n(p)$, and will diverge whenever $\lambda_n(p)>1$, allowing us to define a critical control rate for each $n$ as
L000768	\begin{equation} \label{eq:pstarSUPP}
L000769	    \lambda_n(p^\ast_n) = 1 \quad\Rightarrow\quad p^\ast_n = \frac{e^{n\kappa}-1}{e^{n\kappa} - e^{-n\gamma}},
L000770	\end{equation}
L000771	with divergence occurring for $p<p^\ast_n$ as $t\to\infty$.
L000772	For any $\kappa,\gamma>0$ we have $p^\ast_{n+1}>p^\ast_n$, so that operators of higher order require more frequent interventions to control.
L000773	A generic operator $\hat{\mathcal{O}}$ containing terms up to $n$th order in canonical operators can be expanded in terms of the eigenvectors of $\mathbb{T}$.
L000774	This expansion will generically contain $\hat{Z}_k$ terms for all $k\leq n$, and so will diverge at late times for all $p < p^\ast_n$.
L000775	
L000776	
L000777	\section{Classical noise in the control map}\label{sec:classicalnoise}
L000778	
L000779	We can simulate similar features to the full quantum problem but with classical probability distributions using an Ornstein-Uhlenbeck process in phase space: $x$ evolves as
L000780	\begin{equation}
L000781	    \frac{dx}{dt} = -\gamma x + \sqrt{2D} \xi(t),
L000782	\end{equation}
L000783	where $\expval{\xi(t)\xi(s)}=\delta(t-s)$, and similarly for $p$.
L000784	The Fokker-Planck equation for the distribution of values of $x$ (or $p$) is well known
L000785	\begin{equation}
L000786	    \frac{\partial P}{\partial t} = \gamma \frac{\partial}{\partial x}(x P) + D \frac{\partial^2 P}{\partial x^2},
L000787	\end{equation}
L000788	so the distribution evolves with the kernel
L000789	\begin{equation}
L000790	    K(x,t;x',t') = \sqrt{\frac{\gamma}{2\pi D(1- e^{-2\gamma(t-t')})}} \exp\left[ -\frac{\gamma}{2D} \frac{(x-x' e^{-\gamma(t-t')})^2}{1-e^{-2\gamma(t-t')}}\right].
L000791	\end{equation}
L000792	
L000793	Taking an initial Gaussian distribution, $P(x,0) = \frac{1}{\sqrt{2\pi \sigma}} e^{-\frac{(x - x_0)^2}{2\sigma}}$, convolution with the evolution kernel yields another Gaussian
L000794	\begin{equation}
L000795	    P(x,t) = \frac{1}{\sqrt{2\pi(\sigma e^{-2\gamma t}+\frac{D}{\gamma}(1-e^{-2\gamma t}))}} \exp\left[ -\frac1{2} \frac{(x-x_0 e^{-\gamma t})^2}{\sigma e^{-2\gamma t}+\frac{D}{\gamma}(1-e^{-2\gamma t}))} \right]
L000796	\end{equation}
L000797	Therefore we can track how control changes Gaussian probability distributions
L000798	\begin{equation}
L000799	\begin{aligned}
L000800	    x & \mapsto e^{-\gamma t}x \\
L000801	    \sigma & \mapsto e^{-2\gamma t} \sigma + \tfrac{D}{\gamma}(1 - e^{-2\gamma t})
L000802	\end{aligned}
L000803	\end{equation}
L000804	This will be true for both $x$ and $p$ (or any other basis).
L000805	We also have a chaotic map which behaves the same as indicated in the main text.
L000806	This is the same as what we have for Gaussian bosonic states.
L000807	
L000808	Interleaving chaos and control stochastically, we can build up a distribution of $v_\pm$ and $\sigma_\pm$.
L000809	The controlled ``distribution'' then takes the form
L000810	\begin{equation}
L000811	    P_0(x,p) = \frac1{2\pi D/\gamma} \exp\left[-\frac{\gamma}{2D}(x^2 + p^2)\right].
L000812	\end{equation}
L000813	This form can now be integrated against another Gaussian
L000814	\begin{equation}
L000815	    P(v_+,v_-) = \frac{1}{2\pi\sqrt{\sigma_+\sigma_-}} e^{-\frac{v_+^2}{2\sigma_+} - \frac{v_-^2}{2\sigma_-}},
L000816	\end{equation}
L000817	to give
L000818	\begin{equation}
L000819	    \frac{4\pi D}{\gamma} \int dv_- dv_+ P(v_+, v_-) P_0(v_+, v_-) = \frac{2D/\gamma}{\sqrt{(D/\gamma+ \sigma_+)(D/\gamma+\sigma_-)}}.
L000820	\end{equation}
L000821	The last step is to note that we average over trajectories so there is a \emph{probability distribution} of $\sigma_{\pm}$ which we call $\mathbb{Q}(\sigma_+, \sigma_-)$.
L000822	For this, we can compute the true probability distribution
L000823	\begin{equation}
L000824	    P_{\mathrm{full}}(x_+,x_-) = \int d\sigma_+ d\sigma_- \mathbb{Q}(\sigma_+,\sigma_-) P(x_+,x_-),
L000825	\end{equation}
L000826	and we therefore have the final expression to find the overlap with the noisy controlled distribution
L000827	\begin{equation}
L000828	    \frac{4\pi D}{\gamma} \int dx_- dx_+ P_{\mathrm{full}}(x_+, x_-) P_0(x_+, x_-) = \int d\sigma_+ d\sigma_- \frac{(2D/\gamma) \; \mathbb{Q}(\sigma_+, \sigma_-)}{\sqrt{(D/\gamma+ \sigma_+)(D/\gamma+\sigma_-)}},
L000829	\end{equation}
L000830	If we have quantum-limited noise if $D/\gamma = \frac\hbar2$.
L000831	This shows that the quantum case is related to a noisy classical problem with a particular form of noise (but \emph{only} with the control map).
